# Generates database/487_tprm_baseline_seed.sql from the structured data below.
# Kept with the TPRM sources so a later baseline version can be produced the
# same way (a NEW version -- 487 never rewrites a published one).
import os
import textwrap

def q(s):
    if s is None:
        return "NULL"
    if isinstance(s, bool):
        return "1" if s else "0"
    if isinstance(s, (int, float)):
        return str(s)
    s = str(s)
    assert all(ord(c) < 128 for c in s), s
    return "N'" + s.replace("'", "''") + "'"

def rows(tuples, indent="    "):
    return (",\n").join(indent + "(" + ", ".join(q(v) for v in t) + ")" for t in tuples)

