w("""-- =====================================================================
-- 5. Risk model GRAC_TPRM_STANDARD v1 (the BRD step 2 dimensions)
--    Dimension score = average over its factors of (score / highest
--    option score) x 100. Overall = BLENDED: 40% highest dimension + 60%
--    weighted average, so one severe dimension is not averaged away.
-- =====================================================================
IF NOT EXISTS (SELECT 1 FROM grac_practice.tprm_template
                WHERE organization_id IS NULL AND template_kind = N'RISK_MODEL' AND template_code = N'GRAC_TPRM_STANDARD')
BEGIN
    DECLARE @t BIGINT, @v BIGINT;
    BEGIN TRAN;
    INSERT grac_practice.tprm_template (organization_id, template_kind, template_code, template_name, description, is_default, status, entered_by)
    VALUES (NULL, N'RISK_MODEL', N'GRAC_TPRM_STANDARD', N'GRAC standard engagement risk model',
            N'Eight inherent-risk dimensions from the TPRM BRD with weighted factors, four risk bands and due-diligence tiers. Illustrative baseline - calibrate before relying on it.',
            1, N'Active', N'seed-487');
    SET @t = SCOPE_IDENTITY();
    INSERT grac_practice.tprm_template_version
        (template_id, version_no, status, change_summary, aggregation_method, blend_pct, effective_reduction_pct,
         partial_reduction_pct, residual_floor_pct, deficiency_uplift_pct, created_by, activated_by, activated_dt)
    VALUES (@t, 1, N'ACTIVE', N'GRAC baseline version 1', N'BLENDED', 40, 60, 30, 20, 10, N'seed-487', N'seed-487', SYSUTCDATETIME());
    SET @v = SCOPE_IDENTITY();
    UPDATE grac_practice.tprm_template SET current_version_id = @v WHERE template_id = @t;
""")
w("    INSERT grac_practice.tprm_rm_dimension (version_id, dimension_code, dimension_name, description, weight, display_order)\n    SELECT @v, x.c, x.n, x.d, x.w, x.o FROM (VALUES\n" + rows(dims, "        ") + "\n    ) x(c, n, d, w, o);")
facrows = [(d, code, text, guid, pre, 10*(i+1)) for i,(d,code,text,guid,pre,opts) in enumerate(F)]
w("    INSERT grac_practice.tprm_rm_factor (version_id, dimension_id, factor_code, question_text, guidance, is_mandatory, prefill_source, display_order)\n    SELECT @v, d.dimension_id, x.c, x.t, x.g, 1, x.p, x.o FROM (VALUES\n" + rows(facrows, "        ") + "\n    ) x(dc, c, t, g, p, o)\n    JOIN grac_practice.tprm_rm_dimension d ON d.version_id = @v AND d.dimension_code = x.dc;")
optrows = []
for (d,code,text,guid,pre,opts) in F:
    for j,(oc,ol,sc,m) in enumerate(opts):
        optrows.append((code, oc, ol, sc, m, 10*(j+1)))
w("    INSERT grac_practice.tprm_rm_factor_option (factor_id, option_code, option_label, score, prefill_match_code, display_order)\n    SELECT f.factor_id, x.c, x.l, x.s, x.m, x.o FROM (VALUES\n" + rows(optrows, "        ") + "\n    ) x(fc, c, l, s, m, o)\n    JOIN grac_practice.tprm_rm_factor f ON f.version_id = @v AND f.factor_code = x.fc;")
w("    INSERT grac_practice.tprm_rm_band (version_id, band_code, band_name, min_score, rank_no, color_hex, dd_tier_code)\n    SELECT @v, x.c, x.n, x.m, x.r, x.col, x.t FROM (VALUES\n" + rows(bands, "        ") + "\n    ) x(c, n, m, r, col, t);")
w("    INSERT grac_practice.tprm_rm_tier_rule (version_id, condition_kind, condition_code, min_dd_tier_code)\n    SELECT @v, x.k, x.c, x.t FROM (VALUES\n" + rows(tiers, "        ") + "\n    ) x(k, c, t);")
w("    COMMIT;\n    PRINT '487: risk model GRAC_TPRM_STANDARD v1 created.';\nEND\nELSE PRINT '487: risk model GRAC_TPRM_STANDARD already present -- published versions are never rewritten.';\nGO\n")

