w("-- =====================================================================\n-- 6. Due-diligence questionnaires (core, enhanced, six service-specific)\n-- =====================================================================")
for qs in QS:
    w("IF NOT EXISTS (SELECT 1 FROM grac_practice.tprm_template\n                WHERE organization_id IS NULL AND template_kind = N'QUESTIONNAIRE' AND template_code = " + q(qs['code']) + ")\nBEGIN")
    w("    DECLARE @t BIGINT, @v BIGINT;\n    BEGIN TRAN;")
    w("    INSERT grac_practice.tprm_template (organization_id, template_kind, template_code, template_name, description, status, entered_by)\n    VALUES (NULL, N'QUESTIONNAIRE', " + q(qs['code']) + ", " + q(qs['name']) + ", " + q(qs['desc']) + ", N'Active', N'seed-487');\n    SET @t = SCOPE_IDENTITY();")
    w("    INSERT grac_practice.tprm_template_version\n        (template_id, version_no, status, change_summary, is_core, applies_service_categories, applies_min_tier_rank, created_by, activated_by, activated_dt)\n    VALUES (@t, 1, N'ACTIVE', N'GRAC baseline version 1', " + q(qs['core']) + ", " + q(qs['cats']) + ", " + q(qs['mintier']) + ", N'seed-487', N'seed-487', SYSUTCDATETIME());\n    SET @v = SCOPE_IDENTITY();\n    UPDATE grac_practice.tprm_template SET current_version_id = @v WHERE template_id = @t;")
    secrows = [(c, t, 10*(i+1)) for i,(c,t) in enumerate(qs['sections'])]
    w("    INSERT grac_practice.tprm_q_section (version_id, section_code, title, display_order)\n    SELECT @v, x.c, x.t, x.o FROM (VALUES\n" + rows(secrows, "        ") + "\n    ) x(c, t, o);")
    qrows = []
    for i,x in enumerate(qs['questions']):
        qrows.append((x['section'], x['code'], x['text'], x['guid'], x['rtype'], x['mand'], x['ev'] is not None, x['ev'], x['sg'], x['dim'],
                      x['tier'], x['cats'], x['data'], x['access'], x['parent'], x['trig'], 10*(i+1),
                      (x['ref'] + " (informative)") if x['ref'] else None))
    w("    INSERT grac_practice.tprm_q_question\n        (version_id, section_id, question_code, question_text, guidance, response_type, is_mandatory, evidence_expected,\n         evidence_requirement_code, safeguard_code, dimension_code, min_tier_rank, applies_service_categories, applies_min_data_rank,\n         applies_access_codes, parent_question_code, trigger_option_codes, weight, display_order, source_authority, source_document,\n         source_version, source_reference, applicability_note, is_regulatory)\n    SELECT @v, s.section_id, x.qc, x.qt, x.g, x.rt, x.m, x.ee, x.er, x.sg, x.dc, x.tr, x.sc, x.dr, x.ac, x.pq, x.tg, 1, x.o,\n           " + q(PROV[0]) + ", " + q(PROV[1]) + ", " + q(PROV[2]) + ", x.ref,\n           N'Illustrative baseline question. Not a regulatory requirement unless the organization establishes its source and applicability.', 0\n    FROM (VALUES\n" + rows(qrows, "        ") + "\n    ) x(sec, qc, qt, g, rt, m, ee, er, sg, dc, tr, sc, dr, ac, pq, tg, o, ref)\n    JOIN grac_practice.tprm_q_section s ON s.version_id = @v AND s.section_code = x.sec;")
    orows = []
    for x in qs['questions']:
        if x['rtype'] in ("YES_NO","SINGLE","MULTI"):
            opts = x['opts'] or YN
            for j,(oc,ol,sc,fl,sev) in enumerate(opts):
                orows.append((x['code'], oc, ol, sc, fl, sev, 10*(j+1)))
    if orows:
        w("    INSERT grac_practice.tprm_q_option (question_id, option_code, option_label, score, flags_deficiency, deficiency_severity_code, display_order)\n    SELECT qq.question_id, x.c, x.l, x.s, x.f, x.sev, x.o FROM (VALUES\n" + rows(orows, "        ") + "\n    ) x(qc, c, l, s, f, sev, o)\n    JOIN grac_practice.tprm_q_question qq ON qq.version_id = @v AND qq.question_code = x.qc;")
    w("    COMMIT;\n    PRINT '487: questionnaire " + qs['code'] + " v1 created.';\nEND\nELSE PRINT '487: questionnaire " + qs['code'] + " already present -- not rewritten.';\nGO\n")

